CREATE OR REPLACE VIEW public.complaint_queue WITH (security_invoker=true) AS SELECT c.id,c.org_id,c.reference,c.seq,c.received_at,c.channel,c.country_code,c.language,c.complainant_name,c.complainant_email,c.complainant_phone,c.customer_ref,c.vulnerable,c.vulnerable_note,c.product,c.category,c.summary,c.desired_outcome,c.assigned_to,c.priority,c.status,c.outcome,c.redress_amount,c.redress_currency,c.goodwill_amount,c.goodwill_currency,c.root_cause_category,c.root_cause_note,c.rule_set_id,c.ack_due,c.final_due,c.extended_due,c.holding_sent_at,c.holding_reason,c.closed_at,c.created_by,c.created_at,c.updated_at,CASE WHEN holding_sent_at IS NOT NULL THEN extended_due ELSE final_due END AS current_due,public.business_days_between(org_id,country_code,CURRENT_DATE,CASE WHEN holding_sent_at IS NOT NULL THEN extended_due ELSE final_due END) AS days_left,c.anonymised_at,c.legal_hold,c.root_cause_id,CASE WHEN c.closed_at IS NULL THEN NULL ELSE (c.closed_at AT TIME ZONE 'UTC')::date <= (CASE WHEN c.holding_sent_at IS NOT NULL AND c.extended_due IS NOT NULL THEN c.extended_due ELSE c.final_due END) END AS resolved_within_deadline FROM public.complaints c;
GRANT SELECT ON public.complaint_queue TO authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.template_versions FROM authenticated;